namespace FIFA08Launcher {
 public partial class LauncherForm {
  bool achievementPopup=true,achievementSound=true;
  Button achievementsButton,optionsButton;
  string FeatureText(string es,string en){return PortUi.English?en:es;}
  void InitializeFeatures(){achievementsButton=new RoundedButton{Text="Logros",Height=26};optionsButton=new RoundedButton{Text="Opciones",Height=26};foreach(var b in new[]{achievementsButton,optionsButton})panelControls.Controls.Add(b);
   achievementsButton.Click+=(s,e)=>{using(var f=new AchievementForm(AchievementCatalogPath(),()=>SetUiEnglish(!PortUi.English,true))){f.Icon=Icon;f.ShowDialog(this);}};
   optionsButton.Click+=(s,e)=>ShowFeatureOptions();RefreshFeatureLanguage();UpdateResponsiveLayout();}
  string AchievementCatalogPath(){if(File.Exists(Path.Combine(rootDir,"..","game","default.xex")))return Path.GetFullPath(Path.Combine(rootDir,"..","data","user","achievements","4541081F","catalog.json"));return Path.Combine(rootDir,File.Exists(Path.Combine(rootDir,"GameData","default.xex"))?"UserData":"analysis/private/native-user","achievements","4541081F","catalog.json");}
  void RefreshFeatureLanguage(){if(achievementsButton==null)return;achievementsButton.Text=FeatureText("Logros","Achievements");optionsButton.Text=FeatureText("Opciones","Options");}
  void LayoutFeatures(int x,int y,int width){if(achievementsButton==null)return;int w=(width-8)/2;achievementsButton.SetBounds(x,y,w,27);optionsButton.SetBounds(x+w+8,y,width-w-8,27);}
  void ShowFeatureOptions(){using(var f=new Form{Text=FeatureText("Opciones de logros","Achievement options"),ClientSize=new Size(470,160),MinimumSize=new Size(486,199),StartPosition=FormStartPosition.CenterParent,BackColor=Color.FromArgb(18,18,21),ForeColor=Color.White,Font=Font,Icon=Icon,MaximizeBox=false,FormBorderStyle=FormBorderStyle.FixedDialog}){
   var pop=new CheckBox{Text=FeatureText("Mostrar avisos de logros","Show achievement notifications"),Checked=achievementPopup,AutoSize=true,Location=new Point(20,20)};
   var sound=new CheckBox{Text=FeatureText("Sonido de logros","Achievement sound"),Checked=achievementSound,AutoSize=true,Location=new Point(20,55)};
   var save=new RoundedButton{Text=FeatureText("Guardar","Save"),DialogResult=DialogResult.OK,Location=new Point(315,110),Size=new Size(135,32)};f.Controls.AddRange(new Control[]{pop,sound,save});f.AcceptButton=save;if(f.ShowDialog(this)==DialogResult.OK){achievementPopup=pop.Checked;achievementSound=sound.Checked;SaveSettings();}
  }}
 }

 public sealed class AchievementForm:Form {
  readonly string path;readonly Action toggle;readonly DataGridView grid=new DataGridView();readonly Label summary=new Label();readonly Button language=new Button();readonly Button reset=new RoundedButton();readonly Timer timer=new Timer{Interval=1000};DateTime stamp;bool english;object[] entries;readonly List<Image> icons=new List<Image>();
  public AchievementForm(string catalog,Action toggleLanguage){path=catalog;toggle=toggleLanguage;Width=1000;Height=680;MinimumSize=new Size(700,450);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(14,14,17);ForeColor=Color.White;Font=new Font("Segoe UI",10);english=PortUi.English;
   var top=new Panel{Dock=DockStyle.Top,Height=70,Padding=new Padding(14)};summary.Dock=DockStyle.Fill;language.Dock=DockStyle.Right;language.Width=80;language.FlatStyle=FlatStyle.Flat;language.Click+=(s,e)=>{if(toggle!=null)toggle();else PortUi.English=!PortUi.English;english=PortUi.English;Render();};top.Controls.Add(summary);top.Controls.Add(language);grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.BackgroundColor=BackColor;grid.BorderStyle=BorderStyle.None;grid.EnableHeadersVisualStyles=false;grid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(35,35,40);grid.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;grid.DefaultCellStyle.BackColor=Color.FromArgb(24,24,28);grid.DefaultCellStyle.ForeColor=Color.White;grid.DefaultCellStyle.SelectionBackColor=PortUi.Accent;grid.DefaultCellStyle.SelectionForeColor=Color.White;grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.RowTemplate.Height=62;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;
   grid.Columns.Add(new DataGridViewImageColumn{ImageLayout=DataGridViewImageCellLayout.Zoom,FillWeight=12,DefaultCellStyle=new DataGridViewCellStyle{NullValue=null}});grid.Columns.Add("state","");grid.Columns.Add("name","");grid.Columns.Add("score","");grid.Columns.Add("description","");grid.Columns[1].FillWeight=23;grid.Columns[2].FillWeight=55;grid.Columns[3].FillWeight=10;grid.Columns[4].FillWeight=105;var bottom=new Panel{Dock=DockStyle.Bottom,Height=60,Padding=new Padding(14,10,14,10)};reset.Dock=DockStyle.Right;reset.Width=210;reset.Click+=(s,e)=>ResetProgress();bottom.Controls.Add(reset);Controls.Add(grid);Controls.Add(top);Controls.Add(bottom);timer.Tick+=(s,e)=>Reload();timer.Start();Reload();Disposed+=(s,e)=>{timer.Stop();timer.Dispose();foreach(var image in icons)image.Dispose();icons.Clear();};}
  void ResetProgress(){
   if(AchievementProgress.GameRunning()){MessageBox.Show(this,english?"Close FIFA 08 before resetting achievements.":"Cierra FIFA 08 antes de restablecer los logros.",Text,MessageBoxButtons.OK,MessageBoxIcon.Information);return;}
   string question=english?"Reset all local achievement progress?\n\nSaved games, settings and editor changes will be kept. This cannot be undone.":"\u00bfRestablecer todo el progreso local de logros?\n\nSe conservar\u00e1n las partidas, los ajustes y los cambios del editor. Esta acci\u00f3n no se puede deshacer.";
   if(MessageBox.Show(this,question,english?"Reset achievements":"Restablecer logros",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;
   try{AchievementProgress.Reset(path,AchievementProgress.GameRunning);entries=null;stamp=DateTime.MinValue;Reload();MessageBox.Show(this,english?"Achievement progress reset. You can earn them again.":"Logros restablecidos. Ya puedes volver a conseguirlos.",Text,MessageBoxButtons.OK,MessageBoxIcon.Information);}
   catch(Exception error){if(!(error is InvalidDataException)&&!(error is IOException)&&!(error is UnauthorizedAccessException)&&!(error is InvalidOperationException)&&!(error is ArgumentException))throw;MessageBox.Show(this,(english?"Could not complete the reset: ":"No se pudo completar el restablecimiento: ")+error.Message,Text,MessageBoxButtons.OK,MessageBoxIcon.Error);}
  }
  static string TextValue(Dictionary<string,object> row,string key){object v;return row.TryGetValue(key,out v)?Convert.ToString(v):"";}
  public void Reload(){try{if(!File.Exists(path)){entries=null;Render();return;}var next=File.GetLastWriteTimeUtc(path);if(entries!=null&&next==stamp)return;string data;using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream))data=reader.ReadToEnd();var all=new JavaScriptSerializer{MaxJsonLength=4*1024*1024}.DeserializeObject(data) as Dictionary<string,object>;if(all==null)throw new InvalidDataException();if(TextValue(all,"title_id")!="4541081F")throw new InvalidDataException();object values;if(!all.TryGetValue("achievements",out values)||!(values is object[]))throw new InvalidDataException();var parsed=(object[])values;foreach(var value in parsed){var row=value as Dictionary<string,object>;if(row==null||!row.ContainsKey("unlocked")||!(row["unlocked"] is bool)||!row.ContainsKey("score")||!(row["score"] is int))throw new InvalidDataException();}entries=parsed;stamp=next;Render();}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}catch(InvalidOperationException){} }
  public void SetPresentationLanguage(bool en){english=en;Render();}
  void Render(){Text=english?"FIFA 08 — Achievements":"FIFA 08 — Logros";language.Text=english?"EN | ES":"ES | EN";reset.Text=english?"Reset achievements":"Restablecer logros";reset.Enabled=entries!=null||File.Exists(AchievementProgress.StatePath(path));grid.Columns[1].HeaderText=english?"Status":"Estado";grid.Columns[2].HeaderText=english?"Achievement":"Logro";grid.Columns[3].HeaderText="G";grid.Columns[4].HeaderText=english?"Description":"Descripción";grid.Rows.Clear();foreach(var image in icons)image.Dispose();icons.Clear();if(entries==null){summary.Text=english?"Launch FIFA 08 once to load its original achievement catalog.\nProgress is saved locally; online achievements require their original services.":"Inicia FIFA 08 para cargar su catálogo original de logros.\nEl progreso es local; los logros online requieren sus servicios originales.";return;}int unlocked=0,score=0,total=0;string lang=english?"en":"es";
   foreach(Dictionary<string,object> row in entries){bool done=Convert.ToBoolean(row["unlocked"]);int g=Convert.ToInt32(row["score"]);total+=g;if(done){unlocked++;score+=g;}Image icon=null;try{string file=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(path),TextValue(row,"icon")));string boundary=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(path),"icons"))+Path.DirectorySeparatorChar;if(file.StartsWith(boundary,StringComparison.OrdinalIgnoreCase)&&File.Exists(file))using(var f=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var im=Image.FromStream(f)){icon=new Bitmap(im);icons.Add(icon);}}catch(IOException){}catch(ArgumentException){}grid.Rows.Add(icon,done?(english?"Unlocked":"Desbloqueado"):(english?"Locked":"Bloqueado"),TextValue(row,"name_"+lang),g,TextValue(row,(done?"description_":"locked_")+lang));}
   summary.Text=String.Format(english?"{0}/{1} achievements  ·  {2}/{3}G\nLocal progress · F7 opens the in-game list":"{0}/{1} logros  ·  {2}/{3}G\nProgreso local · F7 abre la lista dentro del juego",unlocked,entries.Length,score,total);}
 }
 public static class AchievementProgress {
  public static bool GameRunning(){foreach(var process in System.Diagnostics.Process.GetProcessesByName("fifa08"))using(process){try{if(!process.HasExited)return true;}catch(InvalidOperationException){}}return false;}
  public static string StatePath(string catalog){var dir=new DirectoryInfo(Path.GetDirectoryName(Path.GetFullPath(catalog)));if(dir.Name!="4541081F"||Path.GetFileName(catalog)!="catalog.json")throw new ArgumentException("Unexpected achievement catalog path.");return Path.Combine(dir.Parent.FullName,"4541081F.toml");}
  static void Publish(string file,string text){string temporary=file+".reset.tmp";try{File.WriteAllText(temporary,text,new System.Text.UTF8Encoding(false));if(File.Exists(file))File.Replace(temporary,file,null);else File.Move(temporary,file);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
  public static void Reset(string catalog,Func<bool> isGameRunning){
   if(isGameRunning==null||isGameRunning())throw new InvalidOperationException("Close FIFA 08 before resetting achievements.");
   string state=StatePath(catalog);string cleared=null;
   if(File.Exists(catalog)){var serializer=new JavaScriptSerializer{MaxJsonLength=4*1024*1024};var data=serializer.DeserializeObject(File.ReadAllText(catalog)) as Dictionary<string,object>;object title,values;if(data==null||!data.TryGetValue("title_id",out title)||Convert.ToString(title)!="4541081F"||!data.TryGetValue("achievements",out values)||!(values is object[]))throw new InvalidDataException("Invalid achievement catalog.");foreach(var value in (object[])values){var row=value as Dictionary<string,object>;if(row==null)throw new InvalidDataException("Invalid achievement entry.");row["unlocked"]=false;row["unlocked_at"]=0;}cleared=serializer.Serialize(data);}
   if(isGameRunning())throw new InvalidOperationException("Close FIFA 08 before resetting achievements.");
   Directory.CreateDirectory(Path.GetDirectoryName(state));Publish(state,"# Achievement unlock state - managed by ReXGlue runtime\n\n[unlocked]\n");
   if(cleared!=null)try{Publish(catalog,cleared);}catch{File.Delete(catalog);throw;}
  }
 }

}
